  "bond.torika.2": "そばにいてもいいよ。",
  "bond.torika.3": "今日は何をしようか？",
  "bond.torika.4": "きみの足音はわかる。",
  "bond.torika.5": "一緒にいると落ち着く。",
  "bond.torika.6": "背中はわたしが守る。",
  "bond.torika.7": "待ってた。",
  "bond.torika.8": "きみが来ると安心する。",
  "bond.torika.9": "最後まで一緒に行くよ。",
  "bond.torika.10": "わたしたちの庭園は、わたしが守る。",
  "bond.rex.0": "触るな。",
  "bond.rex.1": "怖くないみたいだな？",
  "bond.rex.2": "少しは面白いじゃない。",
  "bond.rex.3": "次の狩りも一緒に来い。",
  "bond.rex.4": "お前の匂いは覚えた。",
  "bond.rex.5": "私のそばから離れるな。",
  "bond.rex.6": "お前を狙うやつは私が噛む。",
  "bond.rex.7": "今日も遅いじゃない。",
  "bond.rex.8": "命令よりお前の声がいい。",
  "bond.rex.9": "私の群れはお前だけだ。",
  "bond.rex.10": "永遠にお前の味方でいる。",
  "bond.spino.0": "…どうしたの？",
  "bond.spino.1": "水辺が恋しい。",
  "bond.spino.2": "静かにしていてもいいよ。",
  "bond.spino.3": "きみの話をもっと聞かせて。",
  "bond.spino.4": "今日の波は穏やかだね。",
  "bond.spino.5": "一緒に歩くのは好き。",
  "bond.spino.6": "危なければ私の後ろへ。",
  "bond.spino.7": "きみが来ると思ってた。",
  "bond.spino.8": "この都市にも慣れてきた。",
  "bond.spino.9": "きみのそばが私の水辺。",
  "bond.spino.10": "どこへでも一緒に流れていこう。",
  "bond.generic.0": "まだ少し慣れないな。",
  "bond.generic.1": "今日も会えたね。",
  "bond.generic.2": "少しずつ慣れてきている。",
  "bond.generic.3": "一緒にミッションへ行こう。",
  "bond.generic.4": "きみが来るとうれしい。",
  "bond.generic.5": "そばにいてもいいよ。",
  "bond.generic.6": "今回も手を貸すよ。",
  "bond.generic.7": "待ってた。",
  "bond.generic.8": "わたしたちはいい仲間だ。",
  "bond.generic.9": "長く一緒にいたい。",
  "bond.generic.10": "これからもよろしく。",
