  "dialogue.stage-1-5-greenhouse-echo.promise.body": "記録しておこう。この道を進み続けても、この小さな庭園が忘れられないように。",
  "dialogue.interaction-central-dialogue-02.signal.speaker": "トリカ",
  "dialogue.interaction-central-dialogue-02.signal.body": "ガラスの回廊の下で、古い呼び出し信号が繰り返されています。",
  "dialogue.interaction-central-dialogue-02.choice.speaker": "研究員",
  "dialogue.interaction-central-dialogue-02.choice.body": "記録装置のどの層から復元しようか？",
  "dialogue.interaction-central-dialogue-02.choice.choice.0": "音声層から復元する",
  "dialogue.interaction-central-dialogue-02.choice.choice.1": "移動経路から復元する",
